<?php
namespace Tests\Feature;
use App\Models\Company;use App\Models\Job;use App\Models\JobApplication;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class RecruitmentManagementTest extends TestCase{use RefreshDatabase;public function test_company_and_candidate_manage_messages_and_interview():void{[$owner,$candidate,$application]=$this->process();$this->actingAs($owner,'sanctum')->getJson('/api/v1/company/applications')->assertOk()->assertJsonCount(1,'data');$this->actingAs($owner,'sanctum')->getJson("/api/v1/company/applications/{$application->id}")->assertOk()->assertJsonPath('data.status','viewed');$this->actingAs($owner,'sanctum')->patchJson("/api/v1/company/applications/{$application->id}/status",['status'=>'shortlisted'])->assertOk();$this->actingAs($owner,'sanctum')->postJson("/api/v1/company/applications/{$application->id}/messages",['body'=>'Nos gustaría conocerte.'])->assertCreated();$interview=$this->actingAs($owner,'sanctum')->postJson("/api/v1/company/applications/{$application->id}/interviews",['title'=>'Entrevista inicial','scheduled_at'=>now()->addDay()->toIso8601String(),'duration_minutes'=>30,'format'=>'video','location_or_link'=>'https://meet.example.test/abc'])->assertCreated()->json('data.id');$this->actingAs($candidate,'sanctum')->getJson("/api/v1/candidate/applications/{$application->id}/process")->assertOk()->assertJsonCount(1,'data.messages')->assertJsonCount(1,'data.interviews');$this->actingAs($candidate,'sanctum')->postJson("/api/v1/candidate/applications/{$application->id}/messages",['body'=>'Confirmo disponibilidad.'])->assertCreated();$this->actingAs($candidate,'sanctum')->postJson("/api/v1/candidate/interviews/{$interview}/respond",['response'=>'accepted'])->assertOk()->assertJsonPath('data.status','accepted');}public function test_other_company_cannot_see_application():void{[,,$application]=$this->process();$outsider=User::factory()->create(['account_type'=>'company']);$this->actingAs($outsider,'sanctum')->getJson('/api/v1/company/profile');$this->actingAs($outsider,'sanctum')->getJson("/api/v1/company/applications/{$application->id}")->assertNotFound();}private function process():array{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Empresa Uno','slug'=>'empresa-uno','status'=>'active']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$job=Job::create(['company_id'=>$company->id,'created_by'=>$owner->id,'slug'=>'vacante-uno','title'=>'Desarrollador','summary'=>'Vacante','location'=>'Santo Domingo','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active','published_at'=>now()]);$candidate=User::factory()->create(['account_type'=>'candidate']);$application=JobApplication::create(['job_id'=>$job->id,'user_id'=>$candidate->id,'status'=>'submitted','profile_snapshot'=>['name'=>$candidate->name,'email'=>$candidate->email,'profile'=>['professional_title'=>'Developer']],'applied_at'=>now()]);return[$owner,$candidate,$application];}}
